function renderWorld(w){currentWorld=w;const x=worldData()[w];setText('worldContent',`<div class="world-card"><div><span class="tag">${esc(x.kind)}</span><h3>${esc(x.title)}</h3><p>${esc(x.stance)}</p><div class="world-evidence">${x.evidence.map((e,i)=>`<div><b>${i<2?'OBSERVED / CONSTRAINED':i===2?'CURRENT INTERPRETATION':'OPEN QUESTION'}</b>${esc(e)}</div>`).join('')}</div></div><div><div class="world-score">${esc(x.score)}<small>${esc(x.scoreLabel)}</small></div><div class="world-callout"><b>ThermoBase contribution</b><p>${esc(x.thermo)}</p></div></div></div>`);setText('worldSources',x.sources.length?`<b>Current sources</b>${x.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`).join('')}`:'<b>Benchmark</b><span>Earth is the known-life control; no planetary compatibility score is applied.</span>');
 const p=D.pathways;plot('pathwayCompare',[{x:p.map(x=>x.score),y:p.map(x=>x.pathway),type:'bar',orientation:'h',text:p.map(x=>x.interpretation),hovertemplate:'%{y}<br>Compatibility %{x}/14<br>%{text}<extra></extra>'}],{xaxis:{title:'Ordinal compatibility score / 14',range:[0,14]},margin:{l:225,r:25,t:35,b:45},title:{text:'Enceladus pathway discrimination · compatibility, not probability',font:{size:13}}});
 const evidence={enceladus:[5,4,3,2,1],europa:[4,4,3,2,1],trappist:[2,3,3,2,1],k218:[3,3,3,2,1],earth:[5,5,5,1,0]}[w];plot('worldEvidenceLadder',[{x:['Direct observation','Strong constraint','Inference','Hypothesis','Unknown'],y:evidence,type:'bar',hovertemplate:'%{x}<br>relative evidence level %{y}<extra></extra>'}],{yaxis:{range:[0,5]},title:{text:`Evidence maturity · ${x.title}`,font:{size:13}}});
 const nodes=['H₂','CO₂','CH₄','H₂O','hydrothermal chemistry','methanogens','abiotic methane'];plot('enceladusNetwork',[{type:'sankey',node:{label:nodes,pad:22,thickness:18},link:{source:[0,1,4,5,6],target:[2,2,0,2,2],value:[8,7,5,6,6]}}],{title:{text:'Conceptual redox logic for the Enceladus case',font:{size:13}},margin:{l:5,r:5,t:42,b:5}});plot('abioticRadar',[{type:'scatterpolar',r:[3,3,2,3,2,3],theta:['Internal temperature','Rheology','Lithology','Abiotic organics','Ocean transport','Isotopic baseline'],fill:'toself',name:'Uncertainty to reduce'}],{polar:{radialaxis:{range:[0,3],tickvals:[1,2,3],ticktext:['lower','medium','high']}},showlegend:false,title:{text:'What the 2026 framework says must be constrained',font:{size:13}}});
 const worldRows=[['Enceladus','Plume-accessible',1],['Europa','Ocean world',0],['TRAPPIST-1 e','Remote exoplanet',0],['K2-18 b','Atmospheric target',0],['Earth','Known biosphere',2]];plot('worldComparison',[{x:worldRows.map(x=>x[0]),y:worldRows.map(x=>x[2]),type:'bar',customdata:worldRows.map(x=>x[1]),hovertemplate:'%{x}<br>Framework state: %{y}<br>%{customdata}<extra></extra>'}],{yaxis:{tickvals:[0,1,2],ticktext:['Not scored','Case study','Known-life control'],range:[0,2.3]},title:{text:'Why the worlds are not assigned a common life score',font:{size:13}}});
 $$('[data-world]').forEach(b=>b.classList.toggle('active',b.dataset.world===w));
}

function showRecord(id){const r=D.records.find(x=>String(x.record_id)===String(id));if(!r)return;openChat();addChat('assistant',`<strong>${esc(r.name)}</strong><br><span class="reaction">Record ${esc(r.record_id)}</span><br>Domain: ${esc(r.domain||'—')} · Phylum: ${esc(r.phylum||'—')}<br>Environment: ${esc(r.environment||'—')}<br>Tmin/Topt/Tmax: ${r.min_temp_c??'—'} / ${r.avg_optimum_temp_c??'—'} / ${r.max_temp_c??'—'} °C<br>pHopt: ${r.avg_optimum_ph??'—'} · Pressure: ${r.optimum_pressure_mpa??'—'} MPa<br>Pathways: ${esc(r.metabolism_pathways||'—')}<br>Compounds: ${esc(r.extracted_compounds||'—')}<br>QC: ${esc(r.final_qc_record_status_v71||'—')}`)}
function updateChatContext(){const active=$('.nav.active');const n=filtered().length;setText('chatContext',`Current context: ${active?.textContent?.replace(/^\s*\d+\s*/,'').trim()||'Overview'} · ${n.toLocaleString()} filtered records`)}
function openChat(){const c=$('#researchChat');if(!c)return;c.classList.add('open');c.setAttribute('aria-hidden','false');$('#chatFab').style.display='none';updateChatContext();setTimeout(()=>$('#chatQuestion')?.focus(),40)}
function closeChat(){const c=$('#researchChat');if(!c)return;c.classList.remove('open');c.setAttribute('aria-hidden','true');$('#chatFab').style.display=''}
function addChat(role,text){const body=$('#chatBody');if(!body)return;const d=document.createElement('div');d.className='chat-msg '+role;d.innerHTML=`<b>${role==='user'?'You':'ThermoBase'}</b><p>${text}</p>`;body.appendChild(d);body.scrollTop=body.scrollHeight}
function chatVisual(kind='physiology'){const a=filtered().filter(r=>num(r.avg_optimum_temp_c)!=null&&num(r.avg_optimum_ph)!=null);const box=$('#chatVisual');if(!box)return;box.classList.add('active');box.innerHTML='<div id="chatPlot" class="plot"></div>';plot('chatPlot',[{x:a.map(r=>num(r.avg_optimum_temp_c)),y:a.map(r=>num(r.avg_optimum_ph)),mode:'markers',type:'scattergl',text:a.map(r=>r.name),customdata:a.map(r=>r.record_id),hovertemplate:'<b>%{text}</b><br>Topt %{x} °C<br>pHopt %{y}<extra></extra>'}],{xaxis:{title:'Topt (°C)'},yaxis:{title:'pHopt'},title:{text:`Filtered physiological space · ${a.length} records`,font:{size:12}}})}
function chatAnswer(q){const l=q.toLowerCase(),a=filtered(),total=a.length;
 if(/complete.*thermal|thermal.*complete|tmin|topt.*missing/.test(l))return `<strong>${D.completeness.thermal_complete.toLocaleString()}</strong> records have complete Tmin/Topt/Tmax envelopes. Missing values: Tmin ${D.missing_counts.min_temp_c}, Topt ${D.missing_counts.avg_optimum_temp_c}, Tmax ${D.missing_counts.max_temp_c}. There are 0 thermal envelope ordering violations. <small>Source: ThermoBase QC layer.</small>`;
 if(/complete.*p[hH]|p[hH].*missing|p[hH].*coverage/.test(l))return `<strong>${D.completeness.ph_complete.toLocaleString()}</strong> records have complete pHmin/pHopt/pHmax envelopes. Missing: pHmin ${D.missing_counts.min_ph}, pHopt ${D.missing_counts.avg_optimum_ph}, pHmax ${D.missing_counts.max_ph}. There are 0 complete-envelope ordering violations. <small>Source: ThermoBase QC layer.</small>`;
 if(/337|fields|columns|schema|architecture/.test(l))return `ThermoBase has <strong>337 structured fields</strong>. The schema is partitioned into ${Object.entries(D.schema_groups).map(([k,v])=>`<b>${esc(k)}</b> (${v})`).join(', ')}. Use Evidence & quality → 337-field architecture to browse the actual release schema.`;
 if(/hydrogen oxidation|h2 oxidation/.test(l)&&/lineage|grouped|stress|model|predict/.test(l))return `H₂ oxidation falls from random-fold environment-only ROC-AUC <strong>0.815</strong> to phylum-grouped <strong>0.213</strong>. The apparent random-CV environmental signal therefore does not survive lineage control. <small>Source: final lineage-controlled ML.</small>`;
 if(/methanogenesis/.test(l)&&/ml|predict|model|lineage|grouped/.test(l))return `Methanogenesis has random environment-only ROC-AUC <strong>0.953</strong>; combined reaches 1.000. But grouped validation is <strong>not estimable</strong> because all 52 positives are Euryarchaeota. That is not lineage-independent environmental evidence.`;
 if(/lineage|grouped|stress/.test(l))return `Phylum-grouped environment-only ROC-AUC: sulfate reduction <strong>0.838</strong>, sulfur reduction <strong>0.835</strong>, iron reduction <strong>0.852</strong>, fermentation <strong>0.858</strong>, H₂ oxidation <strong>0.213</strong>. Methanogenesis is not estimable under this split.`;
 if(/extreme|80.*c|80°|high temperature/.test(l)&&/model|classifier|ml|predict/.test(l))return `The Topt ≥80°C classifier uses <strong>${D.extreme.n.toLocaleString()}</strong> records with <strong>${D.extreme.positive}</strong> positives: ROC-AUC ${fmt(D.extreme.roc_auc,3)}, PR-AUC ${fmt(D.extreme.pr_auc,3)}, balanced accuracy ${fmt(D.extreme.balanced_accuracy,3)}.`;
 if(/14.?\/ ?14|probability.*life|chance.*life|enceladus.*score/.test(l))return `The Enceladus matrix gives hydrogenotrophic methanogenesis <strong>14/14</strong>. This is an <strong>ordinal compatibility score across 14 criteria</strong>, not a probability of life. The 2026 abiotic-baseline framework emphasizes that CH₄ isotope or chirality signals remain ambiguous unless internal temperature, rheology, lithology, abiotic organic inventory and ocean transport are constrained.`;
 if(/search|find/.test(l)){const term=l.match(/methane|hydrogen|h2|sulfate|sulfur|iron|co2|carbon dioxide|acetate|nitrate/);if(term){const t=term[0];const hits=D.records.filter(r=>[r.name,r.metabolism_pathways,r.extracted_compounds,r.predicted_biosignature_species,r.environment].some(v=>String(v||'').toLowerCase().includes(t))).slice(0,10);return `<strong>${hits.length}</strong> matching records for <b>${esc(t)}</b>: ${hits.map(r=>`<br>• ${esc(r.name)} — ${esc(r.environment||'—')} — ${esc(r.metabolism_pathways||'—')}`).join('')||'<br>No matching record in the release.'}`}}
 if(/chemical|compound|donor|acceptor|product|role/.test(l))return `The chemistry layer contains <strong>800</strong> records with no extracted compounds, <strong>264</strong> closed high-confidence records, <strong>109</strong> partial high-confidence records with unresolved remainder, and <strong>65</strong> unresolved-context records. The rule is explicit: compound mention ≠ automatically assigned metabolic role.`;
 if(/how many|number of|records|organisms|dataset/.test(l))return `The full release contains <strong>${D.meta.records.toLocaleString()} organisms</strong> and <strong>${D.meta.columns} structured fields</strong>. The current filter context contains <strong>${total.toLocaleString()}</strong> records.`;
 if(/median.*temperature|topt/.test(l))return `Median available Topt in the current filter is <strong>${fmt(median(vals(a,'avg_optimum_temp_c')),1)} °C</strong>.`;
 if(/median.*p[hH]|optimum p[hH]/.test(l))return `Median available pHopt in the current filter is <strong>${fmt(median(vals(a,'avg_optimum_ph')),1)}</strong>.`;
 if(/show|plot|graph|visual|chart/.test(l))return `I can generate a temperature × pH plot from the current filter. Add “temperature and pH” to the question and I will render it below.`;
 return `I could not support that question from the local ThermoBase research layer. Try asking about <b>thermal QC</b>, <b>pH coverage</b>, <b>337 fields</b>, <b>chemistry roles</b>, <b>lineage-controlled ML</b>, a compound/pathway search, or the <b>Enceladus 14/14 score</b>.`}
function submitChat(q){q=q.trim();if(!q)return;addChat('user',esc(q));addChat('assistant',chatAnswer(q));const l=q.toLowerCase();if(/show|plot|graph|visual|chart/.test(l)&&/temperature|temp|p[hH]|physiolog/.test(l))chatVisual()}

function bind(){
 $$('.nav').forEach(b=>b.onclick=()=>go(b.dataset.view));$$('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));
 ['fDomain','fEnvironment','fTopt','fPh','fMet'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{renderPhys();updateChatContext()}));
 $('#resetFilters')?.addEventListener('click',()=>{['fDomain','fEnvironment','fTopt','fPh','fMet'].forEach(id=>{if($('#'+id))$('#'+id).value=''});go('physiology')});$('#themeToggle')?.addEventListener('click',toggleTheme);
 $('#metSearch')?.addEventListener('input',e=>renderMetSearch(e.target.value));$('#clearMet')?.addEventListener('click',()=>{$('#metSearch').value='';renderMetSearch('')});
 $('#schemaSearch')?.addEventListener('input',renderSchema);$('#schemaGroup')?.addEventListener('change',renderSchema);
 $('#chatFab')?.addEventListener('click',openChat);$('#chatClose')?.addEventListener('click',closeChat);$('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#chatQuestion');submitChat(q.value);q.value=''});
 $$('#mlTabs [data-ml]').forEach(b=>b.onclick=()=>{currentML=b.dataset.ml;$$('#mlTabs [data-ml]').forEach(x=>x.classList.toggle('active',x.dataset.ml===currentML));renderML()});
 document.addEventListener('click',e=>{const rec=e.target.closest('[data-record]');if(rec)showRecord(rec.dataset.record);const w=e.target.closest('[data-world]');if(w)renderWorld(w.dataset.world);const q=e.target.closest('[data-chatq]');if(q){openChat();submitChat(q.dataset.chatq)}const ep=e.target.closest('[data-envpath]');if(ep&&activeEnv)drillEnvironment(activeEnv,ep.dataset.envpath);const nav=e.target.closest('[data-jump]');if(nav)go(nav.dataset.jump)});
 window.addEventListener('scroll',()=>{const den=document.body.scrollHeight-innerHeight;$('#progress').style.width=(den>0?scrollY/den*100:0)+'%'});
}
document.addEventListener('keydown',e=>{if(e.target===$('#chatQuestion')&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chatForm')?.requestSubmit()}if(e.key==='Escape'&&$('#researchChat')?.classList.contains('open'))closeChat()});
window.addEventListener('resize',()=>document.querySelectorAll('.js-plotly-plot').forEach(el=>{try{Plotly.Plots.resize(el)}catch{}}));
fetch('data/thermobase.json').then(r=>{if(!r.ok)throw new Error('data fetch failed');return r.json()}).then(d=>{D=d;init()}).catch(e=>{console.error(e);if($('#dataStatus'))$('#dataStatus').textContent='research layer unavailable — check data/thermobase.json'});
